export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const GATE_X = [-1.15, 0.15, 1.35];
  const GATE_Y = [1.05, 1.40, 1.05];
  const GATE_Z = [-0.85, 0.25, 1.05];

  let kThrust = 21.5;
  let mEst = 0.725;
  let thrustFilt = 0.45;
  let prevThrust = 0.45;

  let vyHat = 0;
  let vxHat = 0, vzHat = 0;
  let dxHat = 0, dzHat = 0;
  let intX = 0, intY = 0, intZ = 0;

  let committedGate = -1;
  let padCut = false;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      thrustFilt += (prevThrust - thrustFilt) * 0.22;

      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);

      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (obs.t < 0.005) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      } else {
        if (p.y > 0.11) {
          const ayPred = kThrust * thrustFilt * dirY - (0.42 / mEst) * vyHat - 9.81;
          vyHat += ayPred * dt;
          const evy = v.y - vyHat;
          vyHat += 0.35 * evy;
          if (prevThrust > 0.15 && prevThrust < 0.90 && dirY > 0.75) {
            kThrust = clamp(kThrust + 3.5 * evy * (thrustFilt * dirY), 16.5, 27.5);
            mEst = clamp(15.5 / kThrust, 0.60, 0.85);
          }
        } else {
          vyHat = v.y;
        }

        const uThrust = kThrust * thrustFilt;
        const axKnown = uThrust * dirX - (0.42 / mEst) * vxHat;
        const azKnown = uThrust * dirZ - (0.42 / mEst) * vzHat;

        vxHat += (axKnown + dxHat) * dt;
        const evx = v.x - vxHat;
        vxHat += 0.45 * evx;
        if (p.y > 0.10) dxHat = clamp(dxHat + 6.5 * evx, -4.5, 4.5);

        vzHat += (azKnown + dzHat) * dt;
        const evz = v.z - vzHat;
        vzHat += 0.45 * evz;
        if (p.y > 0.10) dzHat = clamp(dzHat + 6.5 * evz, -4.5, 4.5);
      }

      let tx = p.x, ty = 1.05, tz = p.z;
      let vxFf = 0, vyFf = 0, vzFf = 0;

      if (obs.gateIndex < 3) {
        padCut = false;
        const gi = obs.gateIndex;
        const gx = obs.nextGate.centre.x;
        const gy = obs.nextGate.centre.y;
        const gz = obs.nextGate.centre.z;

        // If we just passed the previous gate, exit cleanly in +x before turning laterally
        if (gi > 0 && p.x < GATE_X[gi - 1] + 0.20) {
          tx = GATE_X[gi - 1] + 0.35;
          ty = GATE_Y[gi - 1];
          tz = GATE_Z[gi - 1];
          vxFf = 0.6;
        } else if (p.x > gx + 0.02) {
          // Missed gate: go around safely outside the gate frame in z
          committedGate = -1;
          const zSide = (p.z >= gz ? 1 : -1) * 0.62;
          if (Math.abs(p.z - gz) < 0.52) {
            tx = p.x + 0.05;
            ty = gy;
            tz = gz + zSide;
          } else {
            tx = gx - 0.45;
            ty = gy;
            tz = gz + zSide;
          }
        } else {
          ty = gy;
          tz = gz;
          const dy = Math.abs(gy - p.y);
          const dz = Math.abs(gz - p.z);
          const dyPred = Math.abs(gy - (p.y + 0.14 * v.y));
          const dzPred = Math.abs(gz - (p.z + 0.14 * v.z));

          const aligned = dy < 0.14 && dz < 0.075 && dyPred < 0.15 && dzPred < 0.08 && Math.abs(v.z) < 0.38 && Math.abs(v.y) < 0.45;
          const safeInside = dy < 0.18 && dz < 0.095 && dyPred < 0.19 && dzPred < 0.10;

          if (aligned && p.x > gx - 0.55) committedGate = gi;
          if (committedGate === gi && !safeInside && p.x < gx - 0.12) committedGate = -1;

          if (committedGate === gi) {
            tx = gx + 0.38;
            vxFf = 0.65;
          } else {
            tx = gx - 0.38;
          }
        }
      } else {
        const px = obs.pad.centre.x, pz = obs.pad.centre.z;
        const distPad = Math.hypot(px - p.x, pz - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (padCut) {
          if (distPad > 0.125) padCut = false;
          else {
            prevThrust = 0;
            return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
          }
        }

        if (distPad < 0.095 && p.y <= 0.088 && speedHoriz < 0.25 && Math.abs(v.y) < 0.30 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.16) {
          padCut = true;
          prevThrust = 0;
          return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
        }

        tx = px;
        tz = pz;
        if (p.x < GATE_X[2] + 0.18) {
          tx = GATE_X[2] + 0.32;
          ty = GATE_Y[2];
          tz = GATE_Z[2];
        } else if (distPad > 0.35) {
          ty = Math.max(0.45, Math.min(1.0, 0.25 + 0.75 * distPad));
        } else if (distPad > 0.11 || speedHoriz > 0.28) {
          ty = 0.22;
        } else {
          // Gentle controlled descent
          ty = Math.max(0.05, p.y - 0.28 * 0.01 - 0.10);
          vyFf = -0.22;
        }
      }

      const ex = tx - p.x;
      const ey = ty - p.y;
      const ez = tz - p.z;

      if (Math.abs(ex) < 0.25 && p.y > 0.10) intX = clamp(intX + ex * dt, -0.35, 0.35);
      else intX *= 0.98;
      if (Math.abs(ez) < 0.25 && p.y > 0.10) intZ = clamp(intZ + ez * dt, -0.35, 0.35);
      else intZ *= 0.98;
      if (Math.abs(ey) < 0.35 && p.y > 0.09) intY = clamp(intY + ey * dt, -0.45, 0.45);

      const axDes = clamp(5.2 * clamp(ex, -0.65, 0.65) + 4.0 * (vxFf - v.x) + 1.8 * intX, -4.2, 4.2);
      const azDes = clamp(5.8 * clamp(ez, -0.65, 0.65) + 4.3 * (vzFf - v.z) + 2.2 * intZ, -4.2, 4.2);
      const ayDes = clamp(6.5 * clamp(ey, -0.60, 0.60) + 4.2 * (vyFf - v.y) + 2.5 * intY, -4.0, 5.0);

      const fx = axDes + (0.42 / mEst) * v.x - dxHat;
      const fz = azDes + (0.42 / mEst) * v.z - dzHat;
      const fy = Math.max(2.5, 9.81 + ayDes + (0.42 / mEst) * v.y);

      const fBodyX = cy * fx - sy * fz;
      const fBodyZ = sy * fx + cy * fz;

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.22) ? 0.28 : 0.52;
      const pitch = clamp(Math.atan2(fBodyX, fy), -maxTilt, maxTilt);
      const roll = clamp(-Math.atan2(fBodyZ, Math.hypot(fBodyX, fy)), -maxTilt, maxTilt);

      const fTotal = fy / Math.max(0.65, dirY);
      const thrust = clamp(fTotal / kThrust, 0.05, 1.0);
      prevThrust = thrust;

      return { thrust, roll, pitch, yawRate: clamp(-2.5 * att.yaw, -2, 2) };
    },
  };
}

