export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const GATE_X = [-1.15, 0.15, 1.35];
  const GATE_Y = [1.05, 1.40, 1.05];
  const GATE_Z = [-0.85, 0.25, 1.05];

  let kThrust = 21.5;
  let mEst = 0.725;
  let thrustFilt = 0.45;
  let prevThrust = 0.45;

  let vyHat = 0;
  let vxHat = 0, vzHat = 0;
  let dxHat = 0, dzHat = 0;
  let intX = 0, intY = 0, intZ = 0;

  let committedGate = -1;
  let settleCount = 0;
  let padCut = false;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;
      const dt = 0.01;

      thrustFilt += (prevThrust - thrustFilt) * 0.22;

      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);

      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (obs.t < 0.005) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      } else {
        if (p.y > 0.11) {
          const ayPred = kThrust * thrustFilt * dirY - (0.42 / mEst) * vyHat - 9.81;
          vyHat += ayPred * dt;
          const evy = v.y - vyHat;
          vyHat += 0.38 * evy;
          if (prevThrust > 0.15 && prevThrust < 0.90 && dirY > 0.75) {
            kThrust = clamp(kThrust + 3.8 * evy * (thrustFilt * dirY), 16.5, 27.5);
            mEst = clamp(15.5 / kThrust, 0.60, 0.85);
          }
        } else {
          vyHat = v.y;
        }

        const uThrust = kThrust * thrustFilt;
        const axKnown = uThrust * dirX - (0.42 / mEst) * vxHat;
        const azKnown = uThrust * dirZ - (0.42 / mEst) * vzHat;

        vxHat += (axKnown + dxHat) * dt;
        const evx = v.x - vxHat;
        vxHat += 0.50 * evx;
        if (p.y > 0.10) dxHat = clamp(dxHat + 8.5 * evx, -5.5, 5.5);

        vzHat += (azKnown + dzHat) * dt;
